1	// PROBE-ONLY: src/ui/screen.ts as W2-01b's brief D9 leaves it (post-W2-01b predecessor stub).
2	import { createInterface } from 'node:readline';
3	
4	export interface Turn<S, R> { readonly state: S; readonly out: readonly string[]; readonly result?: R }
5	export interface Screen<S, R> { readonly start: Turn<S, R>; readonly next: (state: S, line: string) => Turn<S, R> }
6	export interface LineIO { readonly write: (text: string) => void; readonly ask: (prompt: string) => Promise<string | undefined> } // undefined = EOF
7	
8	const DEFAULT_PROMPT = '> ';
9	
10	interface Session<S, R> { readonly screen: Screen<S, R>; readonly io: LineIO; readonly prompt: string }
11	
12	const writeAll = (io: LineIO, lines: readonly string[]): void => {
13	  lines.forEach(line => {
14	    io.write(line);
15	  });
16	};
17	
18	/** One asked line → one turn; a turn's `out` is written before its result returns. */
19	const step = async <S, R>(session: Session<S, R>, turn: Turn<S, R>): Promise<R | undefined> => {
20	  const line = await session.io.ask(session.prompt);
21	  if (line === undefined) return undefined;
22	  const next = session.screen.next(turn.state, line);
23	  writeAll(session.io, next.out);
24	  return next.result === undefined ? step(session, next) : next.result;
25	};
26	
27	export const runScreen = <S, R>(screen: Screen<S, R>, io: LineIO, prompt = DEFAULT_PROMPT): Promise<R | undefined> => {
28	  writeAll(io, screen.start.out);
29	  return step({ screen, io, prompt }, screen.start);
30	};
31	
32	/** Lines are read through readline's async iterator: none is lost when stdin is piped, and EOF reads as undefined. */
33	export const lineIO = (input: NodeJS.ReadableStream, output: NodeJS.WritableStream): LineIO => {
34	  const lines = createInterface({ input, terminal: false })[Symbol.asyncIterator]();
35	  return {
36	    write: text => {
37	      output.write(`${text}\n`);
38	    },
39	    ask: async prompt => {
40	      output.write(prompt);
41	      const next = await lines.next();
42	      return next.done === true ? undefined : next.value;
43	    },
44	  };
45	};
